Codescale_labels &lt;- c("0", "1-10", "11-20", "21-30", "31+")

mpxnyc::neighborhood_sf_obj |&gt;
   sf::st_as_sf() |&gt;
  dplyr::left_join(make_tabledata_residence(), by = "neighborhood") |&gt;
  dplyr::mutate(count = ifelse(is.na(count), 0, count)) |&gt;
  dplyr::mutate(count_cat = cut(count, c(-1,0,10,20,30,76), scale_labels)) |&gt;
  dplyr::arrange(-count) |&gt;
  ggplot2::ggplot() +
  ggplot2::geom_sf(data = mpxnyc::community_sf_obj, fill = "white", linewidth = 0, color = NA) +
  ggplot2::geom_sf(data = mpxnyc::community_sf_obj, fill = "#009BE8", linewidth = 0, color = NA, alpha = 0.1) +
  ggplot2::geom_sf(ggplot2::aes(alpha = count_cat), linewidth = 0, fill = "#009BE8", color = "#C5EFFF") +
  ggplot2::geom_sf(data = mpxnyc::community_sf_obj, fill = NA, linewidth = 0.3, color = "black") +
  ggplot2::scale_alpha_discrete("Participant\ncount") +
  theme_mpxnyc_blank(
    plot.background = ggplot2::element_rect(fill = "white"),
    legend.position = "right"
    )






Figure 6.1: Number of participants by neighborhood in New York City
MPX NYC participants reflect a vivid cross-section of queer and trans New York. They lived in familiar queer neighborhoods—from Hell’s Kitchen to Bedford-Stuy—and brought with them diverse experiences of health, identity, and connection. This section paints a portrait of who they were and how they were connected.
